27	    /** Fixed city-to-region table backing the {@code REGION} fallback when the postcode resolves none. */
28	    private static final Map<String, String> CITY_REGIONS = Map.of(
29	            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
30	
31	    private CustomerCode() {
32	    }
33	
34	    /**
35	     * The full {@code '<REGION>-<HASH8>'} code for the given normalized telephone, last name, postcode
36	     * and city.
37	     */
38	    public static String of(String normalizedTelephone, String lastName, String postcode, String city) {
39	        return region(postcode, city) + "-" + hash8(normalizedTelephone, lastName);
40	    }
41	
42	    /**
43	     * Derives {@code REGION}: the postcode range first (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099),
44	     * then the {@link #CITY_REGIONS} city table, then {@code 'UNKNOWN'}. This disambiguates cities that
45	     * share a name and is the region embedded in every {@code customerCode}.
46	     */
47	    public static String region(String postcode, String city) {
48	        String region = regionForPostcode(postcode);
49	        if (region != null) {
50	            return region;
51	        }
52	        return CITY_REGIONS.getOrDefault(city, "UNKNOWN");
53	    }
54	
55	    /**
56	     * The {@code REGION} prefix carried by a {@code customerCode} of the form {@code '<REGION>-<HASH8>'},
57	     * or {@code null} when the code is absent or malformed.
58	     */
59	    public static String regionOf(String customerCode) {
60	        if (customerCode == null) {
61	            return null;
62	        }
63	        int dash = customerCode.indexOf('-');
64	        return dash > 0 ? customerCode.substring(0, dash) : null;
65	    }
66	
67	    /** {@code HASH8}: the first 8 upper-case hex characters of SHA-256 of {@code normalizedTelephone + lastName}. */
68	    public static String hash8(String normalizedTelephone, String lastName) {
69	        String tel = normalizedTelephone == null ? "" : normalizedTelephone;
70	        String last = lastName == null ? "" : lastName;
71	        return shaHex(tel + last, 8);
72	    }
73	
74	    /**
75	     * Derives the region from a 4-digit postcode: NSW 2000-2099, VIC 3000-3099, QLD 4000-4099.
76	     * Returns {@code null} when the postcode is absent, non-numeric or in no known range.
77	     */
78	    private static String regionForPostcode(String postcode) {
79	        if (postcode == null) {
80	            return null;
81	        }
82	        int code;
83	        try {
84	            code = Integer.parseInt(postcode.trim());
85	        } catch (NumberFormatException ex) {
86	            return null;
87	        }
88	        if (code >= 2000 && code <= 2099) {
89	            return "NSW";
90	        }
91	        if (code >= 3000 && code <= 3099) {
92	            return "VIC";
93	        }
94	        if (code >= 4000 && code <= 4099) {
95	            return "QLD";
96	        }
97	        return null;
98	    }
99	
100	    /** First {@code n} upper-case hex characters of SHA-256 of {@code value}. */
101	    private static String shaHex(String value, int n) {
102	        try {
103	            byte[] digest = MessageDigest.getInstance("SHA-256")
104	                    .digest(value.getBytes(StandardCharsets.UTF_8));
105	            StringBuilder sb = new StringBuilder(digest.length * 2);
106	            for (byte b : digest) {
107	                sb.append(String.format("%02X", b));
108	            }
109	            return sb.substring(0, n);
110	        }
111	        catch (NoSuchAlgorithmException e) {
112	            throw new IllegalStateException("SHA-256 not available", e);
113	        }
114	    }
115	}
