3	import java.time.DayOfWeek;
4	import java.time.LocalDate;
5	import java.util.Set;
6	
7	import net.officefloor.plugin.variable.Val;
8	import org.springframework.samples.petclinic.model.Owner;
9	
10	/**
11	 * Resolves a create-owner request's effective registration date and forces it onto a business day.
12	 * When the client supplied no date, the server's current date is used; a supplied date is kept.
13	 * Either way, if the effective date falls on a Saturday, Sunday or a listed public holiday it is
14	 * rolled forward to the next non-holiday weekday, so the persisted {@code registrationDate} is
15	 * always a business day.
16	 *
17	 * <p>Runs after {@link BuildOwner} has mapped the request onto the entity and mutates that same
18	 * entity in place (via {@code @Val}), so {@link CheckDailyLimit}, {@link SaveOwner} and any value
19	 * derived from the registration date (e.g. the membership number's year segment) all see the
20	 * adjusted date.
21	 */
22	public class DefaultRegistrationDate {
23	
24	    /** Fixed public holidays the business-day roll skips. */
25	    private static final Set<LocalDate> HOLIDAYS = Set.of(
26	            LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
27	            LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"), LocalDate.parse("2026-12-28"));
28	
29	    public void service(@Val Owner owner) {
30	        LocalDate date = owner.getRegistrationDate();
31	        if (date == null) {
32	            date = LocalDate.now();
33	        }
34	        owner.setRegistrationDate(toBusinessDay(date));
35	    }
36	
37	    /**
38	     * Roll a date forward to the next business day: weekends and listed public holidays are skipped;
39	     * a non-holiday weekday is returned unchanged.
40	     */
41	    private static LocalDate toBusinessDay(LocalDate date) {
42	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY
43	                || HOLIDAYS.contains(date)) {
44	            date = date.plusDays(1);
45	        }
46	        return date;
47	    }
48	}
