1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.HashSet;
4	import java.util.Set;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.repository.OwnerRepository;
9	
10	/**
11	 * Assigns the owner's {@code customerCode}, the region-and-hash identity {@code '<REGION>-<HASH8>'}
12	 * where REGION is the region code derived from the postcode (falling back to the city, then
13	 * {@code 'UNKNOWN'}) and HASH8 is the first 8 upper-case hex characters of SHA-256 over
14	 * {@code normalizedTelephone + lastName} (e.g. {@code 'NSW-1A2B3C4D'}). See {@link CustomerCode}.
15	 *
16	 * <p>The base code is a pure function of the owner's already-normalized telephone, last name,
17	 * postcode and city. When that base collides with an existing owner's {@code customerCode}, this
18	 * step de-duplicates it by appending {@code '-<n>'} with the smallest {@code n >= 2} that makes the
19	 * result unique across all persisted owners. Runs after {@link BuildOwner} has mapped the request
20	 * onto the entity (telephone already normalized to E.164 by {@link ValidateOwnerFields}) and before
21	 * {@link SaveOwner}, within the same write transaction so the uniqueness check and the insert see
22	 * one consistent view.
23	 */
24	public class AssignCustomerCode {
25	
26	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
27	        String base = CustomerCode.of(
28	                owner.getTelephone(), owner.getLastName(), owner.getPostcode(), owner.getCity());
29	
30	        Set<String> taken = new HashSet<>();
31	        for (Owner existing : ownerRepository.findAll()) {
32	            if (existing != owner && existing.getCustomerCode() != null) {
33	                taken.add(existing.getCustomerCode());
34	            }
35	        }
36	
37	        String code = base;
38	        for (int n = 2; taken.contains(code); n++) {
39	            code = base + "-" + n;
40	        }
41	        owner.setCustomerCode(code);
42	    }
43	}
